package org.brightstats.stats;
import java.util.*;
import org.apache.commons.math3.linear.*;

/** Available-pair sample covariances and Pearson correlations, with actual overlap counts. */
public final class PairwiseMoments {
    private PairwiseMoments(){}
    public record Fit(List<String> names,int sourceRows,long missingCells,int emptyRows,int[][] counts,double[] means,
                      double[][] covariance,double[][] correlation,double covarianceMinimumEigenvalue,double correlationMinimumEigenvalue,List<String> warnings){
        public Fit{names=List.copyOf(names);counts=Arrays.stream(counts).map(int[]::clone).toArray(int[][]::new);means=means.clone();covariance=Matrices.copy(covariance);correlation=Matrices.copy(correlation);warnings=List.copyOf(warnings);}
        @Override public int[][] counts(){return Arrays.stream(counts).map(int[]::clone).toArray(int[][]::new);}
        @Override public double[] means(){return means.clone();}
        @Override public double[][] covariance(){return Matrices.copy(covariance);}
        @Override public double[][] correlation(){return Matrices.copy(correlation);}
    }
    static int width(double[][] data){if(data==null||data.length<3||data.length>1000000||data[0]==null||data[0].length<1||data[0].length>256||(long)data.length*data[0].length>5000000L)throw new IllegalArgumentException("Pairwise analysis requires 3–1,000,000 rows, 1–256 variables and at most five million cells.");int p=data[0].length;for(var row:data){if(row==null||row.length!=p)throw new IllegalArgumentException("Ragged pairwise data.");for(double value:row)if(Double.isInfinite(value))throw new IllegalArgumentException("Pairwise input accepts finite values or missing NaN, never infinity.");}return p;}
    public static Fit fit(double[][] data,List<String> names){int p=width(data);if(names.size()!=p||new HashSet<>(names).size()!=p||names.stream().anyMatch(value->value==null||value.isBlank()))throw new IllegalArgumentException("Name pairwise variables uniquely.");int[][] counts=new int[p][p];double[][] covariance=new double[p][p],correlation=new double[p][p];double[] means=new double[p];Arrays.fill(means,Double.NaN);long missing=0;int empty=0;for(var row:data){boolean all=true;for(double value:row)if(Double.isNaN(value))missing++;else all=false;if(all)empty++;}
        for(int a=0;a<p;a++)for(int b=0;b<=a;b++){Matrices.interrupted();int count=0;double mx=0,my=0,vx=0,vy=0,cross=0;for(int row=0;row<data.length;row++){if((row&4095)==0)Matrices.interrupted();double x=data[row][a],y=data[row][b];if(Double.isNaN(x)||Double.isNaN(y))continue;count++;double dx=x-mx,dy=y-my;mx+=dx/count;my+=dy/count;vx+=dx*(x-mx);vy+=dy*(y-my);cross+=dx*(y-my);}counts[a][b]=counts[b][a]=count;double cov=count>=2?cross/(count-1):Double.NaN,r=count>=2&&vx>0&&vy>0?cross/Math.sqrt(vx)/Math.sqrt(vy):Double.NaN;if(Double.isInfinite(cov)||Double.isInfinite(r)||count>0&&(!Double.isFinite(mx)||!Double.isFinite(my))||!Double.isFinite(vx)||!Double.isFinite(vy))throw new IllegalArgumentException("Pairwise moment calculation exceeds the finite numeric range.");if(Double.isFinite(r)){if(Math.abs(r)>1+1e-10)throw new IllegalArgumentException("Invalid pairwise correlation exceeds its numerical range.");r=Math.max(-1,Math.min(1,r));}covariance[a][b]=covariance[b][a]=cov;correlation[a][b]=correlation[b][a]=r;if(a==b&&count>0)means[a]=mx;}
        double covMin=minimum(covariance),corMin=minimum(correlation);List<String>warnings=new ArrayList<>();warnings.add("Each covariance/correlation uses only its available pair, with pair-specific means and variances; sample covariance divisor is n_pair - 1. Marginal means use all observed cells in each variable.");warnings.add("Different pairs can have different sample sizes. Pairwise correlation is not obtained by dividing pairwise covariance by marginal standard deviations. Pairwise matrices can be indefinite; no PSD repair is applied.");warnings.add("Population/model interpretation of pairwise moments and IID case-bootstrap inference requires an appropriate missingness assumption, such as MCAR. This is not full-information likelihood or a general MAR correction.");if(!covarianceAdmissible(covariance))warnings.add("The sample covariance is incomplete, singular or not positive definite; covariance-based estimation may be unavailable.");if(!Double.isFinite(corMin)||corMin<=1e-10)warnings.add("The correlation matrix is incomplete, singular or not positive definite; moment-based component estimation is unavailable.");if(empty>0)warnings.add(empty+" original rows contain no observed selected variables; they remain disclosed in the source population and case-resampling scheme.");return new Fit(names,data.length,missing,empty,counts,means,covariance,correlation,covMin,corMin,warnings);
    }
    public static boolean covarianceAdmissible(double[][] covariance){int p=covariance.length;double[][] normalized=new double[p][p];for(int i=0;i<p;i++){if(!(covariance[i][i]>0)||!Double.isFinite(covariance[i][i]))return false;for(int j=0;j<p;j++){normalized[i][j]=covariance[i][j]/Math.sqrt(covariance[i][i])/Math.sqrt(covariance[j][j]);if(!Double.isFinite(normalized[i][j]))return false;}}return minimum(normalized)>1e-10;}
    private static double minimum(double[][] matrix){for(var row:matrix)for(double value:row)if(!Double.isFinite(value))return Double.NaN;return Matrices.minEigenvalue(matrix);}
    /** Internal covariance-equivalent centered design; these are not original observations or case scores. */
    static double[][] design(Fit moments){int p=moments.names.size();if(p<2||!Double.isFinite(moments.correlationMinimumEigenvalue)||moments.correlationMinimumEigenvalue<=1e-10)throw new IllegalArgumentException("Pairwise component estimation requires a complete positive-definite correlation matrix (minimum eigenvalue > 1e-10).");double[][] l=new CholeskyDecomposition(new Array2DRowRealMatrix(moments.correlation,false),1e-10,1e-12).getL().getData();int n=p+1;double[][] x=new double[n][p];for(int row=0;row<n;row++)for(int basis=0;basis<p;basis++){double h=row<=basis?1/Math.sqrt((basis+1.0)*(basis+2)):row==basis+1?-(basis+1)/Math.sqrt((basis+1.0)*(basis+2)):0;if(h!=0)for(int column=0;column<p;column++)x[row][column]+=Math.sqrt(n)*h*l[column][basis];}return x;}
    static double[][] pack(double[][] data){int p=width(data);if((long)data.length*p*2>5000000L)throw new IllegalArgumentException("Case resampling of values plus missingness masks exceeds five million packed cells.");double[][] packed=new double[data.length][2*p];for(int row=0;row<data.length;row++)for(int column=0;column<p;column++){double value=data[row][column];packed[row][column]=Double.isNaN(value)?0:value;packed[row][column+p]=Double.isNaN(value)?0:1;}return packed;}
    static double[][] unpack(double[][] packed){int width=Matrices.width(packed,3);if(width%2!=0)throw new IllegalArgumentException("Invalid packed missingness width.");int p=width/2;double[][] data=new double[packed.length][p];for(int row=0;row<data.length;row++)for(int column=0;column<p;column++){double present=packed[row][column+p];if(present!=0&&present!=1)throw new IllegalArgumentException("Invalid packed missingness mask.");data[row][column]=present==0?Double.NaN:packed[row][column];}return data;}
}
